sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
   if (isLoading || newValue === '') {
      return;
   }

   //Type appropriate comment here, and begin script below
   var ga = new GlideAjax('x_1523510_alloca_0.AllocateNowUtils');
    ga.addParam('sysparm_name', 'checkManagerAlreadyUsed');
    ga.addParam('sysparm_manager_id', newValue);
    ga.addParam('sysparm_base_id', g_form.getUniqueValue());

    ga.getXMLAnswer(function(answer) {
        if (answer == 'true') {
            g_form.clearValue('manager');

            g_form.addErrorMessage(
                'This Manager already manages another base.'
            );
        }
    });

}
